CREATE TABLE category_catalog(id INTEGER PRIMARY KEY,items TEXT NOT NULL DEFAULT '[]',revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE admin_auth(id INTEGER PRIMARY KEY,password_hash TEXT,salt TEXT,iterations INTEGER NOT NULL DEFAULT 100000,revision INTEGER NOT NULL DEFAULT 0,recovery_hash TEXT,changed_at TEXT);
CREATE TABLE auth_attempt(key TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL);
ALTER TABLE admin_session ADD COLUMN auth_revision INTEGER NOT NULL DEFAULT 0;
